import{_ as a,o as e,c as r,ag as o}from"./chunks/framework.D45daZFh.js";const u=JSON.parse('{"title":"儿童青少年肥胖食养指南（2024年版）","description":"国家卫健委《儿童青少年肥胖食养指南（2024年版）》要点导读：兼顾生长发育与肥胖防控，家庭学校共同参与。","frontmatter":{"title":"儿童青少年肥胖食养指南（2024年版）","issuer":"国家卫生健康委办公厅","source_tier":"一级来源","version":"2024年版","published":"2024-02","document_no":"国卫办食品函〔2024〕53号","source_url":"https://www.nhc.gov.cn/sps/c100088/202402/9ba512ba8e314a47a181db11d2fa188d/files/1743476134816_82016.pdf","status":"现行","tags":["儿童肥胖","青少年","食养","饮食指导"],"reviewed":false,"description":"国家卫健委《儿童青少年肥胖食养指南（2024年版）》要点导读：兼顾生长发育与肥胖防控，家庭学校共同参与。"},"headers":[],"relativePath":"guides/child-obesity-2024.md","filePath":"guides/child-obesity-2024.md"}'),s={name:"guides/child-obesity-2024.md"};function d(i,t,l,n,c,h){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="儿童青少年肥胖食养指南-2024年版" tabindex="-1">儿童青少年肥胖食养指南（2024年版） <a class="header-anchor" href="#儿童青少年肥胖食养指南-2024年版" aria-label="Permalink to &quot;儿童青少年肥胖食养指南（2024年版）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本导读由 AI 起草，尚未逐条对照原文校验；一切以原文为准。</p></div><blockquote><p><strong>原文出处</strong>：国家卫生健康委办公厅印发（<a href="https://www.nhc.gov.cn/sps/c100088/202402/9ba512ba8e314a47a181db11d2fa188d/files/1743476134816_82016.pdf" target="_blank" rel="noreferrer">官方问答 PDF</a>，指南全文另见<a href="https://www.chinanutri.cn/fgbz/fgbzjszn/" target="_blank" rel="noreferrer">中国疾控中心营养与健康所技术指南页</a>）· 一级来源</p></blockquote><h2 id="这份文件适合谁" tabindex="-1">这份文件适合谁 <a class="header-anchor" href="#这份文件适合谁" aria-label="Permalink to &quot;这份文件适合谁&quot;">​</a></h2><p>超重、肥胖的儿童青少年及其家长，也面向校医、营养指导人员等。</p><h2 id="关键要点-摘要" tabindex="-1">关键要点（摘要） <a class="header-anchor" href="#关键要点-摘要" aria-label="Permalink to &quot;关键要点（摘要）&quot;">​</a></h2><ul><li><strong>生长发育优先</strong>：遵循《中国居民膳食指南（2022）》食物多样、营养均衡的原则，肥胖防控不能牺牲生长发育需求。</li><li><strong>管住高糖高油</strong>：控制含糖饮料、高油高糖零食的摄入。</li><li><strong>家庭与学校共同参与</strong>：饮食行为的改变需要环境支持。</li><li><strong>吃动平衡</strong>：配合规律的身体活动与充足睡眠。</li></ul><h2 id="怎么用这份文件" tabindex="-1">怎么用这份文件 <a class="header-anchor" href="#怎么用这份文件" aria-label="Permalink to &quot;怎么用这份文件&quot;">​</a></h2><p>指南面向不同年龄段给出膳食建议，并附分地区、分季节食谱示例；儿童减重方案建议在专业指导下制定，具体以原文为准。</p><h2 id="溯源信息" tabindex="-1">溯源信息 <a class="header-anchor" href="#溯源信息" aria-label="Permalink to &quot;溯源信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>发布机构</td><td>国家卫生健康委办公厅</td></tr><tr><td>版本</td><td>2024 年版（现行）</td></tr><tr><td>印发时间</td><td>2024 年 2 月（具体日期待核对原文）</td></tr><tr><td>发文字号</td><td>国卫办食品函〔2024〕53号（待人工复核）</td></tr></tbody></table>',11)])])}const p=a(s,[["render",d]]);export{u as __pageData,p as default};
